from pathlib import Path
import json
tid='DEV-PRED-ASTRA-RESULT-NORMALIZE-R5-20261008-N1E132'
state=Path.home()/'.local/state/prediction-project-executor'/(tid+'.json')
receipt=Path.home()/'.local/share/prediction-chat-bridge/dev-task-receipts'/(tid+'.log')
parts=[]
if state.is_file():
    o=json.loads(state.read_text())
    for k in ['task_id','status','exit_code','error','detail','source_commit','worktree','branch']:
        if k in o: parts.append(k.upper()+'='+str(o.get(k)).replace('\n',' ').replace('|','/'))
else: parts.append('STATE_MISSING=1')
if receipt.is_file():
    s=' '.join(receipt.read_text(errors='replace').splitlines())
    parts.append('RECEIPT_TAIL='+s[-3500:].replace('|','/'))
else: parts.append('RECEIPT_MISSING=1')
print('ERROR_CLASS=N1E132_NORMALIZE_EXACT_STATE')
print('ERROR='+'|'.join(parts)[:9000])
raise SystemExit(1)
